def hs_name(code: str) -> str:
    """HS 코드의 품목 영문명. 정확 레벨 없으면 상위 레벨로 폴백."""
    code = (code or '').strip()
    if code in HS_NAMES:
        return HS_NAMES[code]
    # HS6/HS5 → HS4 → HS2 폴백
    for L in (4, 2):
        if len(code) > L and code[:L] in HS_NAMES:
            return HS_NAMES[code[:L]]
    return ''
